def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Check if field starts with a quote
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote represents a single quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check that closing quote is followed by comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        fields.append(''.join(field))
                        # Skip the comma if present
                        if i < len(line) and line[i] == ',':
                            i += 1
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quotes not allowed in unquoted fields
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            # Skip the comma if present
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

